import Foundation
import Security

protocol SecItemAdapter: AnyObject, Sendable {
    func copyMatching(_ query: [String: Any]) -> (OSStatus, AnyObject?)
    func add(_ attributes: [String: Any]) -> OSStatus
    func update(_ query: [String: Any], attributes: [String: Any]) -> OSStatus
    func delete(_ query: [String: Any]) -> OSStatus
}

final class SystemSecItemAdapter: SecItemAdapter, @unchecked Sendable {
    func copyMatching(_ query: [String: Any]) -> (OSStatus, AnyObject?) {
        var result: CFTypeRef?
        let status = SecItemCopyMatching(query as CFDictionary, &result)
        return (status, result)
    }
    func add(_ attributes: [String: Any]) -> OSStatus { SecItemAdd(attributes as CFDictionary, nil) }
    func update(_ query: [String: Any], attributes: [String: Any]) -> OSStatus { SecItemUpdate(query as CFDictionary, attributes as CFDictionary) }
    func delete(_ query: [String: Any]) -> OSStatus { SecItemDelete(query as CFDictionary) }
}

enum CredentialLoadResult: Sendable, Equatable { case none, credential(Credential), unsafe, failure }
enum CredentialSaveResult: Sendable, Equatable { case saved, saveFailure, deletionPending }
enum CredentialDeleteResult: Sendable, Equatable { case complete, pending }

protocol CredentialStoreProtocol: Sendable {
    func load() async -> CredentialLoadResult
    func save(_ credential: Credential) async -> CredentialSaveResult
    func reset() async -> CredentialDeleteResult
    func signOut() async -> CredentialDeleteResult
    func removeDeniedCredential() async -> CredentialDeleteResult
}

actor CredentialStore: CredentialStoreProtocol {
    nonisolated static let service = "com.auditco.ace.client.authentication"
    nonisolated static let lifecycleOperationsAreSynchronous = true
    nonisolated static let deletionUsesAllSynchronisationClasses = true
    nonisolated static let requiresExactCFTypes = true
    private let adapter: SecItemAdapter
    private let expectedAccessGroup: String?

    init(adapter: SecItemAdapter = SystemSecItemAdapter(), expectedAccessGroup: String? = nil) {
        self.adapter = adapter
        self.expectedAccessGroup = expectedAccessGroup
    }

    // These methods contain no suspension point. The actor cannot re-enter a lifecycle call.
    func load() -> CredentialLoadResult {
        let (status, result) = adapter.copyMatching(inventoryQuery())
        if status == errSecItemNotFound { return .none }
        guard status == errSecSuccess, let list = result as? [[String: Any]], !list.isEmpty else {
            return status == errSecSuccess ? .unsafe : .failure
        }
        guard list.count == 1, let account = validatedAccount(in: list[0], exactAccount: nil) else { return .unsafe }
        let (readStatus, readResult) = adapter.copyMatching(exactReadQuery(account: account))
        if readStatus == errSecItemNotFound { return .unsafe }
        guard readStatus == errSecSuccess else { return .failure }
        guard let item = readResult as? [String: Any],
              validatedAccount(in: item, exactAccount: account) != nil,
              let data = cfData(item[kSecValueData as String]), !data.isEmpty,
              let password = String(data: data, encoding: .utf8), !password.isEmpty else { return .unsafe }
        return .credential(Credential(username: account, password: password))
    }

    func save(_ credential: Credential) -> CredentialSaveResult {
        let (inventoryStatus, result) = adapter.copyMatching(inventoryQuery())
        if inventoryStatus == errSecItemNotFound { return addOrUpdateDuplicate(credential) }
        guard inventoryStatus == errSecSuccess, let list = result as? [[String: Any]], list.count == 1,
              let oldAccount = validatedAccount(in: list[0], exactAccount: nil) else { return .deletionPending }
        if oldAccount == credential.username {
            let status = adapter.update(exactUpdateQuery(account: oldAccount), attributes: [kSecValueData as String: Data(credential.password.utf8)])
            if status == errSecSuccess { return .saved }
            return completedDeletion() ? .saveFailure : .deletionPending
        }
        guard completedDeletion() else { return .deletionPending }
        return addOrUpdateDuplicate(credential)
    }

    func reset() -> CredentialDeleteResult { completedDeletion() ? .complete : .pending }
    func signOut() -> CredentialDeleteResult { completedDeletion() ? .complete : .pending }
    func removeDeniedCredential() -> CredentialDeleteResult { completedDeletion() ? .complete : .pending }

    private func addOrUpdateDuplicate(_ credential: Credential) -> CredentialSaveResult {
        let status = adapter.add(addAttributes(credential))
        if status == errSecSuccess { return .saved }
        guard status == errSecDuplicateItem else { return .saveFailure }
        let update = adapter.update(exactUpdateQuery(account: credential.username), attributes: [kSecValueData as String: Data(credential.password.utf8)])
        if update == errSecSuccess { return .saved }
        return completedDeletion() ? .saveFailure : .deletionPending
    }

    private func completedDeletion() -> Bool {
        let status = adapter.delete(serviceDeletionQuery())
        return status == errSecSuccess || status == errSecItemNotFound
    }

    private func inventoryQuery() -> [String: Any] {
        [kSecClass as String: kSecClassGenericPassword,
         kSecAttrService as String: Self.service,
         kSecAttrSynchronizable as String: kSecAttrSynchronizableAny,
         kSecMatchLimit as String: kSecMatchLimitAll,
         kSecReturnAttributes as String: true,
         kSecReturnData as String: false]
    }

    private func exactReadQuery(account: String) -> [String: Any] {
        [kSecClass as String: kSecClassGenericPassword, kSecAttrService as String: Self.service,
         kSecAttrAccount as String: account, kSecAttrSynchronizable as String: false,
         kSecMatchLimit as String: kSecMatchLimitOne, kSecReturnAttributes as String: true,
         kSecReturnData as String: true]
    }

    private func exactUpdateQuery(account: String) -> [String: Any] {
        [kSecClass as String: kSecClassGenericPassword, kSecAttrService as String: Self.service,
         kSecAttrAccount as String: account, kSecAttrSynchronizable as String: false]
    }

    private func serviceDeletionQuery() -> [String: Any] {
        [kSecClass as String: kSecClassGenericPassword, kSecAttrService as String: Self.service,
         kSecAttrSynchronizable as String: kSecAttrSynchronizableAny]
    }

    private func addAttributes(_ credential: Credential) -> [String: Any] {
        [kSecClass as String: kSecClassGenericPassword, kSecAttrService as String: Self.service,
         kSecAttrAccount as String: credential.username, kSecValueData as String: Data(credential.password.utf8),
         kSecAttrAccessible as String: kSecAttrAccessibleWhenUnlockedThisDeviceOnly,
         kSecAttrSynchronizable as String: false]
    }

    private func validatedAccount(in attributes: [String: Any], exactAccount: String?) -> String? {
        guard let service = cfString(attributes[kSecAttrService as String]), service == Self.service,
              let account = cfString(attributes[kSecAttrAccount as String]), !account.isEmpty,
              exactAccount == nil || account == exactAccount,
              let accessible = cfString(attributes[kSecAttrAccessible as String]),
              accessible == (kSecAttrAccessibleWhenUnlockedThisDeviceOnly as String),
              let synchronizable = cfBoolean(attributes[kSecAttrSynchronizable as String]), !synchronizable else { return nil }
        if let group = attributes[kSecAttrAccessGroup as String] {
            guard let group = cfString(group), let expectedAccessGroup, group == expectedAccessGroup else { return nil }
        }
        for key in [kSecAttrCreationDate as String, kSecAttrModificationDate as String] {
            if let value = attributes[key], !isCFType(value, CFDateGetTypeID()) { return nil }
        }
        return account
    }

    private func cfString(_ value: Any?) -> String? {
        guard let value, isCFType(value, CFStringGetTypeID()) else { return nil }
        return value as? String
    }

    private func cfBoolean(_ value: Any?) -> Bool? {
        guard let value, isCFType(value, CFBooleanGetTypeID()) else { return nil }
        return value as? Bool
    }

    private func cfData(_ value: Any?) -> Data? {
        guard let value, isCFType(value, CFDataGetTypeID()) else { return nil }
        return value as? Data
    }

    private func isCFType(_ value: Any, _ typeID: CFTypeID) -> Bool {
        CFGetTypeID(value as CFTypeRef) == typeID
    }
}

import Foundation

struct Credential: Sendable, Equatable {
    let username: String
    let password: String
}

protocol CurrentReleaseTransport: Sendable {
    func fetchCurrentRelease(request: URLRequest) async throws -> (Data, HTTPURLResponse)
}

protocol CurrentReleaseRepository: Sendable {
    func fetchCurrentRelease(credential: Credential) async throws -> ValidatedRelease
}

enum RepositoryError: Error, Sendable, Equatable {
    case denied, unavailable, noConnection, timeout, secureConnection, invalidResponse
}

enum CurrentReleaseRequest {
    static func make(origin: PreviewOrigin, credential: Credential) throws -> URLRequest {
        var request = URLRequest(url: origin.endpointURL())
        request.httpMethod = "GET"
        request.cachePolicy = .reloadIgnoringLocalCacheData
        request.setValue("application/json", forHTTPHeaderField: "Accept")
        let encoded = Data("\(credential.username):\(credential.password)".utf8).base64EncodedString()
        request.setValue("Basic \(encoded)", forHTTPHeaderField: "Authorization")
        return request
    }
}

struct HTTPCurrentReleaseRepository: CurrentReleaseRepository {
    let origin: PreviewOrigin
    let transport: any CurrentReleaseTransport

    func fetchCurrentRelease(credential: Credential) async throws -> ValidatedRelease {
        do {
            let (data, response) = try await transport.fetchCurrentRelease(request: CurrentReleaseRequest.make(origin: origin, credential: credential))
            switch response.statusCode {
            case 200:
                guard isJSON(response.value(forHTTPHeaderField: "Content-Type")) else { throw RepositoryError.invalidResponse }
                do { return try JSONDecoder().decode(ClientReleaseResponse.self, from: data).validated() }
                catch { throw RepositoryError.invalidResponse }
            case 403: throw RepositoryError.denied
            case 503: throw RepositoryError.unavailable
            default: throw RepositoryError.unavailable
            }
        } catch let error as RepositoryError { throw error }
        catch let error as URLError {
            switch error.code {
            case .timedOut: throw RepositoryError.timeout
            case .serverCertificateUntrusted, .serverCertificateHasBadDate, .serverCertificateHasUnknownRoot, .serverCertificateNotYetValid, .clientCertificateRejected, .secureConnectionFailed, .clientCertificateRequired: throw RepositoryError.secureConnection
            default: throw RepositoryError.noConnection
            }
        } catch { throw RepositoryError.noConnection }
    }

    private func isJSON(_ contentType: String?) -> Bool {
        contentType?.split(separator: ";", maxSplits: 1).first.map { $0.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() == "application/json" } ?? false
    }
}

final class RedirectAndTrustDelegate: NSObject, URLSessionTaskDelegate, @unchecked Sendable {
    func urlSession(_ session: URLSession, task: URLSessionTask, willPerformHTTPRedirection response: HTTPURLResponse, newRequest request: URLRequest, completionHandler: @escaping (URLRequest?) -> Void) {
        completionHandler(nil)
    }

    func urlSession(_ session: URLSession, task: URLSessionTask, didReceive challenge: URLAuthenticationChallenge, completionHandler: @escaping (URLSession.AuthChallengeDisposition, URLCredential?) -> Void) {
        completionHandler(.performDefaultHandling, nil)
    }
}

final class URLSessionCurrentReleaseTransport: CurrentReleaseTransport, @unchecked Sendable {
    let session: URLSession
    private let delegate: RedirectAndTrustDelegate

    init() {
        let configuration = URLSessionConfiguration.ephemeral
        configuration.urlCache = nil
        configuration.requestCachePolicy = .reloadIgnoringLocalCacheData
        configuration.httpCookieStorage = nil
        configuration.httpShouldSetCookies = false
        configuration.urlCredentialStorage = nil
        delegate = RedirectAndTrustDelegate()
        session = URLSession(configuration: configuration, delegate: delegate, delegateQueue: nil)
    }

    func fetchCurrentRelease(request: URLRequest) async throws -> (Data, HTTPURLResponse) {
        let (data, response) = try await session.data(for: request)
        guard let response = response as? HTTPURLResponse else { throw RepositoryError.invalidResponse }
        return (data, response)
    }
}

import Foundation

struct ClientReleaseResponse: Codable, Sendable, Equatable {
    let engagementName: String
    let reviewStatus: String
    let releaseVersion: Int
    let publishedAt: String
    let conclusion: ClientConclusion?
    let actions: [ClientAction]

    enum CodingKeys: String, CodingKey {
        case engagementName = "engagement_name", reviewStatus = "review_status"
        case releaseVersion = "release_version", publishedAt = "published_at", conclusion, actions
    }

    func validated() throws -> ValidatedRelease {
        if (engagementName == "Release unavailable" || engagementName == "Engagement not found"),
           reviewStatus.isEmpty, releaseVersion == 0, publishedAt.isEmpty, conclusion == nil, actions.isEmpty {
            return .empty
        }
        guard releaseVersion > 0, !engagementName.isEmpty, !reviewStatus.isEmpty,
              Self.isCanonicalUTC(publishedAt) else { throw ReleaseValidationError.invalid }
        if let conclusion {
            guard !conclusion.title.isEmpty, !conclusion.summary.isEmpty,
                  !conclusion.evidenceReferenceID.isEmpty else { throw ReleaseValidationError.invalid }
        }
        for action in actions {
            guard !action.description.isEmpty, !action.owner.isEmpty,
                  Self.isCalendarDate(action.targetDate), action.status == "OPEN" || action.status == "COMPLETE" else {
                throw ReleaseValidationError.invalid
            }
        }
        return .release(self)
    }

    private static func isCanonicalUTC(_ value: String) -> Bool {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone(secondsFromGMT: 0)
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.isLenient = false
        formatter.dateFormat = "yyyy-MM-dd'T'HH:mm:ss'Z'"
        return formatter.date(from: value).map { formatter.string(from: $0) == value } ?? false
    }

    private static func isCalendarDate(_ value: String) -> Bool {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone(secondsFromGMT: 0)
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.isLenient = false
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter.date(from: value).map { formatter.string(from: $0) == value } ?? false
    }
}

struct ClientConclusion: Codable, Sendable, Equatable {
    let title: String
    let summary: String
    let evidenceReferenceID: String
    enum CodingKeys: String, CodingKey { case title, summary; case evidenceReferenceID = "evidence_reference_id" }
}

struct ClientAction: Codable, Sendable, Equatable {
    let description: String
    let owner: String
    let targetDate: String
    let status: String
    enum CodingKeys: String, CodingKey { case description, owner; case targetDate = "target_date"; case status }
}

enum ValidatedRelease: Sendable, Equatable { case empty, release(ClientReleaseResponse) }
enum ReleaseValidationError: Error { case invalid }

import SwiftUI

enum RetryAction: Sendable, Equatable { case refresh, keychainRead, deletion }

enum ScreenState: Equatable, Sendable {
    case configuration
    case signIn(message: String?)
    case loading
    case release(ClientReleaseResponse, notices: [String])
    case empty
    case failure(message: String, retry: RetryAction)
    case deletionPending(message: String, afterDeletion: String?, deletionOnlyRecovery: Bool)

    enum Presentation: Equatable, Sendable {
        case configuration(message: String)
        case signIn(message: String?)
        case loading
        case release(ClientReleaseResponse, notices: [String])
        case empty(message: String)
        case failure(message: String, retry: RetryAction)
        case deletionPending(message: String, deletionOnlyRecovery: Bool)

        var errorMessage: String? {
            switch self {
            case .configuration(let message), .failure(let message, _), .deletionPending(let message, _):
                return message
            case .signIn(let message):
                return message
            case .loading, .release, .empty:
                return nil
            }
        }
    }

    var presentation: Presentation {
        switch self {
        case .configuration:
            return .configuration(message: "This app is not configured for access.")
        case .signIn(let message):
            return .signIn(message: message)
        case .loading:
            return .loading
        case .release(let release, let notices):
            return .release(release, notices: notices)
        case .empty:
            return .empty(message: "No current release is available.")
        case .failure(let message, let retry):
            return .failure(message: message, retry: retry)
        case .deletionPending(let message, _, let deletionOnlyRecovery):
            return .deletionPending(message: message, deletionOnlyRecovery: deletionOnlyRecovery)
        }
    }
}

@MainActor
final class SessionState: ObservableObject {
    @Published private(set) var screen: ScreenState = .loading {
        didSet {
            if screen.presentation.errorMessage != nil { errorAnnouncementEvent &+= 1 }
        }
    }
    @Published private(set) var errorAnnouncementEvent = 0
    private let configuration: AppConfiguration
    private let store: any CredentialStoreProtocol
    private var repository: (any CurrentReleaseRepository)?
    private var credential: Credential?
    private var generation = 0
    private var credentialGeneration = 0
    private var activeTask: Task<Void, Never>?

    init(configuration: AppConfiguration = AppConfiguration(), store: (any CredentialStoreProtocol)? = nil, repository: (any CurrentReleaseRepository)? = nil) {
        self.configuration = configuration
        self.store = store ?? CredentialStore(expectedAccessGroup: configuration.expectedAccessGroup)
        self.repository = repository
    }

    func start() {
        guard case .success(let origin) = configuration.origin else {
            invalidateRequests(); credential = nil; screen = .configuration; return
        }
        if repository == nil { repository = HTTPCurrentReleaseRepository(origin: origin, transport: URLSessionCurrentReleaseTransport()) }
        activeTask?.cancel()
        activeTask = Task { [weak self] in
            guard let self else { return }
            switch await self.store.load() {
            case .none: self.screen = .signIn(message: nil)
            case .credential(let credential): self.credential = credential; self.beginFetch()
            case .unsafe: self.enterDeletionPending(message: "Saved sign-in must be reset before access.", afterDeletion: nil, deletionOnlyRecovery: true)
            case .failure: self.screen = .failure(message: "Saved sign-in could not be read. Try again.", retry: .keychainRead)
            }
        }
    }

    func signIn(username: String, password: String) {
        guard !username.isEmpty, !password.isEmpty else { screen = .signIn(message: "Enter a username and password."); return }
        guard let repository else { screen = .configuration; return }
        invalidateRequests()
        let candidate = Credential(username: username, password: password)
        screen = .loading
        let requestGeneration = generation
        activeTask = Task { [weak self] in
            guard let self else { return }
            do {
                let release = try await repository.fetchCurrentRelease(credential: candidate)
                guard self.canApply(requestGeneration) else { return }
                switch await self.store.save(candidate) {
                case .saved:
                    guard self.canApply(requestGeneration) else { return }
                    self.credential = candidate; self.credentialGeneration += 1; self.apply(release)
                case .saveFailure: self.screen = .signIn(message: "Sign-in could not be saved. Try again.")
                case .deletionPending: self.enterDeletionPending(message: "Saved sign-in could not be removed. Try again.", afterDeletion: nil, deletionOnlyRecovery: false)
                }
            } catch { self.apply(error: error, generation: requestGeneration) }
        }
    }

    func refresh() { beginFetch() }

    func retry(_ action: RetryAction) {
        switch action {
        case .refresh: beginFetch()
        case .keychainRead: start()
        case .deletion: completeDeletion()
        }
    }

    func resetSavedSignIn() { completeDeletion() }

    func signOut() {
        invalidateRequests(); credential = nil; screen = .loading
        activeTask = Task { [weak self] in
            guard let self else { return }
            if await self.store.signOut() == .complete { self.screen = .signIn(message: nil) }
            else { self.enterDeletionPending(message: "Sign-out could not be completed. Try again.", afterDeletion: nil, deletionOnlyRecovery: false) }
        }
    }

    private func beginFetch() {
        guard let credential, let repository else { return }
        invalidateRequests(); screen = .loading
        let requestGeneration = generation
        let requestCredentialGeneration = credentialGeneration
        activeTask = Task { [weak self] in
            guard let self else { return }
            do {
                let release = try await repository.fetchCurrentRelease(credential: credential)
                guard self.canApply(requestGeneration, credentialGeneration: requestCredentialGeneration) else { return }
                self.apply(release)
            } catch { self.apply(error: error, generation: requestGeneration, credentialGeneration: requestCredentialGeneration) }
        }
    }

    private func apply(_ release: ValidatedRelease) {
        switch release {
        case .empty: screen = .empty
        case .release(let release):
            var notices: [String] = []
            if release.conclusion == nil { notices.append("No conclusion is available.") }
            if release.actions.isEmpty { notices.append("No actions are available.") }
            screen = .release(release, notices: notices)
        }
    }

    private func apply(error: Error, generation: Int, credentialGeneration: Int? = nil) {
        guard canApply(generation, credentialGeneration: credentialGeneration) else { return }
        if let error = error as? RepositoryError {
            switch error {
            case .denied:
                invalidateRequests(); credential = nil
                activeTask = Task { [weak self] in
                    guard let self else { return }
                    if await self.store.removeDeniedCredential() == .complete { self.screen = .signIn(message: "Access denied. Sign in again.") }
                    else { self.enterDeletionPending(message: "Saved sign-in could not be removed. Try again.", afterDeletion: "Access denied. Sign in again.", deletionOnlyRecovery: false) }
                }
            case .unavailable, .invalidResponse: applyRequestFailure(message: "ACE is unavailable. Try again later.")
            case .noConnection: applyRequestFailure(message: "ACE could not be reached. Check your connection and try again.")
            case .timeout: applyRequestFailure(message: "The request timed out. Try again.")
            case .secureConnection: applyRequestFailure(message: "ACE could not establish a secure connection. Try again later.")
            }
        } else { applyRequestFailure(message: "ACE could not be reached. Check your connection and try again.") }
    }

    private func applyRequestFailure(message: String) {
        if credential == nil { screen = .signIn(message: message) }
        else { screen = .failure(message: message, retry: .refresh) }
    }

    private func completeDeletion() {
        let afterDeletion: String?
        let deletionOnlyRecovery: Bool
        if case .deletionPending(_, let after, let deletionOnly) = screen {
            afterDeletion = after
            deletionOnlyRecovery = deletionOnly
        } else {
            afterDeletion = nil
            deletionOnlyRecovery = false
        }
        invalidateRequests(); credential = nil; screen = .loading
        activeTask = Task { [weak self] in
            guard let self else { return }
            if await self.store.reset() == .complete { self.screen = .signIn(message: afterDeletion) }
            else { self.enterDeletionPending(message: "Saved sign-in could not be removed. Try again.", afterDeletion: afterDeletion, deletionOnlyRecovery: deletionOnlyRecovery) }
        }
    }

    private func enterDeletionPending(message: String, afterDeletion: String?, deletionOnlyRecovery: Bool) {
        invalidateRequests(); credential = nil; screen = .deletionPending(message: message, afterDeletion: afterDeletion, deletionOnlyRecovery: deletionOnlyRecovery)
    }

    private func invalidateRequests() { generation += 1; activeTask?.cancel(); activeTask = nil }
    private func canApply(_ requestGeneration: Int, credentialGeneration expected: Int? = nil) -> Bool {
        guard !Task.isCancelled, requestGeneration == generation else { return false }
        if let expected { return expected == credentialGeneration && credential != nil }
        if credential != nil { return true }
        if case .loading = screen { return true }
        return false
    }
}

import Foundation
import SwiftUI
import UIKit

struct RootView: View {
    @ObservedObject var state: SessionState

    var body: some View {
        #if DEBUG
        if let scenario = UITestScenario.current {
            if scenario.usesReleaseScroll {
                ScenarioRootView(scenario: scenario)
            } else {
                ScenarioRootView(scenario: scenario).padding()
            }
        }
        else { content }
        #else
        content
        #endif
    }

    @ViewBuilder private var content: some View {
        let presentation = state.screen.presentation
        Group {
            switch presentation {
            case .configuration(let message):
                SafeMessageView(message: message, action: nil)
            case .signIn(let message):
                SignInView(message: message, submit: state.signIn)
            case .loading:
                ProgressView("Loading")
                    .accessibilityLabel("Loading current release")
            case .release(let release, let notices):
                ReleaseView(release: release, notices: notices, refresh: state.refresh, signOut: state.signOut)
            case .empty(let message):
                CurrentReleaseMessageView(message: message, retry: .refresh, retryAction: state.refresh, signOutAction: state.signOut)
            case .failure(let message, let retry):
                CurrentReleaseMessageView(message: message, retry: retry, retryAction: { state.retry(retry) }, signOutAction: retry == .refresh ? { state.signOut() } : nil)
            case .deletionPending(let message, let deletionOnlyRecovery):
                SafeMessageView(message: message, action: (deletionOnlyRecovery ? "Reset saved sign-in" : "Try again", deletionOnlyRecovery ? state.resetSavedSignIn : { state.retry(.deletion) }))
            }
        }
        .padding(isReleasePresentation(presentation) ? Edge.Set() : .all)
        .modifier(ErrorAnnouncement(message: presentation.errorMessage, event: state.errorAnnouncementEvent))
    }

    private func isReleasePresentation(_ presentation: ScreenState.Presentation) -> Bool {
        if case .release = presentation { return true }
        return false
    }
}

private struct ErrorAnnouncement: ViewModifier {
    let message: String?
    let event: Int

    func body(content: Content) -> some View {
        content
            .onAppear { announce(message) }
            .onChange(of: event) { _, _ in announce(message) }
    }

    private func announce(_ message: String?) {
        guard let message else { return }
        UIAccessibility.post(notification: .announcement, argument: message as NSString)
    }
}

