    private func requiredAppearance() -> String {
        guard let appearance = ProcessInfo.processInfo.environment["ACE_UI_TEST_APPEARANCE"],
              ["light", "dark"].contains(appearance) else {
            XCTFail("ACE_UI_TEST_APPEARANCE must be light or dark")
            return "light"
        }
        return appearance
    }

    private func launch(_ scenario: String, appearance requestedAppearance: String? = nil) -> XCUIApplication {
        let app = XCUIApplication()
        let appearance = requestedAppearance ?? requiredAppearance()
        app.launchEnvironment["ACE_UI_TEST_SCENARIO"] = scenario
        app.launchEnvironment["ACE_UI_TEST_APPEARANCE"] = appearance
        app.launch()
        return app
    }

    private func launchWithNormalDeviceSettings(_ scenario: String) -> XCUIApplication {
        XCTAssertNil(
            ProcessInfo.processInfo.environment["ACE_UI_TEST_APPEARANCE"],
            "Normal-device evidence must not receive a forced appearance"
        )
        let app = XCUIApplication()
        app.launchEnvironment["ACE_UI_TEST_SCENARIO"] = scenario
        app.launchEnvironment.removeValue(forKey: "ACE_UI_TEST_APPEARANCE")
        XCTAssertNil(
            app.launchEnvironment["ACE_UI_TEST_APPEARANCE"],
            "Normal-device launch must omit ACE_UI_TEST_APPEARANCE"
        )
        app.launch()
        return app
    }

    private func requiredNormalDeviceAppearance() -> String {
        guard let appearance = ProcessInfo.processInfo.environment["ACE_EXPECTED_EFFECTIVE_INTERFACE_STYLE"],
              ["light", "dark"].contains(appearance) else {
            XCTFail("ACE_EXPECTED_EFFECTIVE_INTERFACE_STYLE must be light or dark")
            return "light"
        }
        return appearance
    }

    private func requiredNormalDeviceContentSize() -> String {
        let supported = [
            "extra-small", "small", "medium", "large", "extra-large",
            "extra-extra-large", "extra-extra-extra-large", "accessibility-medium",
            "accessibility-large", "accessibility-extra-large",
            "accessibility-extra-extra-large", "accessibility-extra-extra-extra-large"
        ]
        guard let contentSize = ProcessInfo.processInfo.environment["ACE_EXPECTED_CONTENT_SIZE_CATEGORY"],
              supported.contains(contentSize) else {
            XCTFail("ACE_EXPECTED_CONTENT_SIZE_CATEGORY must be supported")
            return "medium"
        }
        return contentSize
    }

    func testCompleteActionClipboardPastesExactly() {
        continueAfterFailure = false
        let actionPayloads = [
            ("Copy action 1", "Action 1\nDescription: Fictional action\nOwner: Fictional owner\nTarget date: 2026-08-25\nStatus: OPEN", "ActionOneClipboardSentinelA"),
            ("Copy action 2", "Action 2\nDescription: Second fictional action\nOwner: Second fictional owner\nTarget date: 2026-08-26\nStatus: COMPLETE", "ActionTwoClipboardSentinelB"),
            ("Copy action 1", "Action 1\nDescription: Fictional action\nOwner: Fictional owner\nTarget date: 2026-08-25\nStatus: OPEN", "ActionOneClipboardSentinelC")
        ]
        let app = launch("multiAction")
        defer { app.terminate() }

        for (position, action) in actionPayloads.enumerated() {
            let (label, expectedPayload, sentinel) = action
            XCTAssertFalse(expectedPayload.contains(sentinel), "Clipboard sentinel must differ from the expected action payload")
            seedNativeClipboard(with: sentinel, in: app)

            let copy = app.buttons[label]
            scrollUntilVisible(copy, in: app, field: label)
            XCTAssertTrue(copy.isHittable, "\(label) must be tappable")
            copy.tap()

            let actionNumber = label.suffix(1)
            let confirmation = app.staticTexts["Copied Action \(actionNumber)."]
            XCTAssertTrue(confirmation.waitForExistence(timeout: 5), "\(label) must show its confirmation")
            addScreenshot(of: app, named: "Native action copied — step \(position + 1) — \(label)")
            if position == 1 {
                XCTAssertTrue(app.staticTexts["Copied Action 1."].exists, "Action 1 confirmation must persist after copying Action 2")
            }
            if position == 2 {
                let actionDescription = app.descendants(matching: .any)
                    .matching(NSPredicate(format: "label == %@", "Action description: Fictional action"))
                    .firstMatch
                XCTAssertEqual(actionDescription.label, "Action description: Fictional action", "First Action 1 copy must keep its description visible")
                XCTAssertTrue(app.staticTexts["Copied Action 2."].exists, "Action 2 confirmation must persist before repeated Action 1 copy")
            }

            let destination = openClipboardTestDestination(in: app)
            XCTAssertEqual(destination.value as? String, "", "Clipboard test destination must be empty before Paste")
            focus(destination, in: app, purpose: "Paste")
            destination.press(forDuration: 1)
            addScreenshot(of: app, named: "Native Paste menu — step \(position + 1) — \(label)")
            let paste = nativeMenuItem("Paste", in: app)
            XCTAssertTrue(paste.waitForExistence(timeout: 5), "Native Paste command must be available for \(label)")
            paste.tap()
            XCTAssertEqual(destination.value as? String, expectedPayload, "Native Paste must reproduce the copied \(label) payload exactly")
            addScreenshot(of: app, named: "Native pasted value — step \(position + 1) — \(label)")
            closeClipboardTestDestination(in: app)
            XCTAssertTrue(confirmation.exists, "\(label) confirmation must persist after the sheet closes")
            if position == 2 {
                XCTAssertEqual(
                    app.descendants(matching: .any)
                        .matching(NSPredicate(format: "label == %@", "Action description: Fictional action"))
                        .firstMatch.label,
                    "Action description: Fictional action",
                    "Repeated Action 1 copy must keep its description visible"
                )
            }
        }
    }

    private func seedNativeClipboard(with sentinel: String, in app: XCUIApplication) {
        let destination = openClipboardTestDestination(in: app)
        focus(destination, in: app, purpose: "Copy")
        destination.typeText(sentinel)
        XCTAssertEqual(destination.value as? String, sentinel, "Clipboard test destination must contain the complete sentinel before Copy")
        destination.doubleTap()
        addScreenshot(of: app, named: "Native clipboard sentinel selected — \(sentinel)")
        let copy = nativeMenuItem("Copy", in: app)
        if !copy.waitForExistence(timeout: 1) {
            let selectAll = nativeMenuItem("Select All", in: app)
            XCTAssertTrue(selectAll.waitForExistence(timeout: 5), "Native Select All command must be available when Copy is absent")
            selectAll.tap()
            addScreenshot(of: app, named: "Native clipboard sentinel select all — \(sentinel)")
        }
        XCTAssertTrue(copy.waitForExistence(timeout: 5), "Native Copy command must be available for clipboard seeding")
        addScreenshot(of: app, named: "Native clipboard sentinel menu — \(sentinel)")
        copy.tap()
        addScreenshot(of: app, named: "Native clipboard sentinel copied — \(sentinel)")
        closeClipboardTestDestination(in: app)
    }

    private func openClipboardTestDestination(in app: XCUIApplication) -> XCUIElement {
        let open = app.buttons["Clipboard test destination"]
